<?php
require __DIR__.'/inc/v11.php';
header('Cache-Control: no-store, private');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');
$token=(string)($_GET['token']??$_POST['token']??'');
if(!preg_match('/^[a-f0-9]{64}$/D',$token)){http_response_code(404);exit('Bağlantı geçersiz.');}
function ek_public_error($message,$code=400){http_response_code($code);exit('<!doctype html><html lang="tr"><meta charset="utf-8"><title>Sözleşme</title><body style="font:16px Arial,sans-serif;max-width:680px;margin:60px auto;padding:20px">'.htmlspecialchars($message,ENT_QUOTES,'UTF-8').'</body></html>');}
try{
 $st=db()->prepare('SELECT l.quote_id,l.contract_hash,l.expires_at,(l.expires_at>NOW()) AS unexpired,l.revoked_at,c.language,c.body,q.quote_no,cu.name FROM ek_contract_share_links l JOIN v11_contracts c ON c.quote_id=l.quote_id JOIN quotes q ON q.id=l.quote_id JOIN customers cu ON cu.id=q.customer_id WHERE l.token_hash=? LIMIT 1');
 $st->execute([hash('sha256',$token)]);$row=$st->fetch(PDO::FETCH_ASSOC);
 if(!$row)ek_public_error('Bağlantının süresi dolmuş veya bağlantı geçersiz.',404);
 $currentHash=hash('sha256',$row['language']."\n".$row['body']);
 if(!hash_equals($row['contract_hash'],$currentHash))ek_public_error('Sözleşme değiştirildi. Güncel bağlantıyı firmadan isteyin.',410);
 $qid=(int)$row['quote_id'];$displayHash=ekDisplayHash(ekLoadContractDisplay(db(),$qid));$signed=false;
 $st=db()->query("SHOW TABLES LIKE 'ek_contract_signatures'");
 if($st->fetchColumn()){$st=db()->prepare('SELECT contract_hash FROM ek_contract_signatures WHERE quote_id=?');$st->execute([$qid]);$old=$st->fetchColumn();$signed=is_string($old)&&hash_equals($currentHash,$old);}
 $transitionMeta=ekRevisionMeta(db(),$qid);if(!$signed&&!empty($transitionMeta['revision_effective_child_id']))ek_public_error('Bu belge tarihsel kayıttır. Güncel sözleşme bağlantısını firmadan isteyin.',410);
 if(!empty($row['revoked_at'])&&!$signed)ek_public_error('Bu bağlantı iptal edilmiş. Yeni bağlantı için firmayla iletişime geçin.',403);
 if(!$signed&&!(int)$row['unexpired'])ek_public_error('Bu bağlantının süresi dolmuş. Yeni bağlantı isteyin.',410);
 $error='';$success=false;
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify();
  if($signed)ek_public_error('Bu sözleşme zaten imzalandı.',409);
  $name=trim((string)($_POST['signer_name']??''));
  if($name===''||mb_strlen($name)>190)throw new RuntimeException('Ad soyad gereklidir.');
  if(($_POST['consent']??'')!=='yes')throw new RuntimeException('Sözleşme onayı gereklidir.');
  $upload=$_FILES['signature_png']??null;
  if(!is_array($upload)||($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($upload['size']??0)<250||$upload['size']>110000||!is_uploaded_file($upload['tmp_name']))throw new RuntimeException('İmza dosyası geçersiz.');
  $bin=file_get_contents($upload['tmp_name']);$dim=$bin!==false?@getimagesizefromstring($bin):false;
  if(!$dim||$dim[2]!==IMAGETYPE_PNG||$dim[0]>1600||$dim[1]>700||substr($bin,0,8)!=="\x89PNG\r\n\x1a\n")throw new RuntimeException('Geçerli PNG imzası alınamadı.');
  ekStoreContractSignature(db(),$qid,$currentHash,$name,$bin,0,hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'',DB_PASS),hash('sha256',$token),is_string($_POST['display_hash']??null)?$_POST['display_hash']:null);
  $success=true;$signed=true;
  try{
   $admins=db()->query("SELECT id FROM users WHERE LOWER(role) IN ('admin','administrator')")->fetchAll(PDO::FETCH_COLUMN);
   if($admins){
    $notify=db()->prepare('INSERT INTO ek_notifications(recipient_id,quote_id,event_type,title,body) VALUES (?,?,?,?,?)');
    foreach($admins as $recipient)$notify->execute([(int)$recipient,$qid,'contract_signed','Müşteri sözleşmeyi imzaladı',mb_substr($name.' · '.$row['quote_no'].' · '.date('d.m.Y H:i'),0,500)]);
   }
  }catch(Throwable $notificationError){error_log('Contract notification failed: '.$notificationError->getMessage());}
 }
}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof PDOException?'İşlem tamamlanamadı. Lütfen firmayla iletişime geçin.':'İşlem tamamlanamadı: '.$e->getMessage();}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>EKŞİOĞLU | Sözleşme İmzası</title><style>body{margin:0;background:#f3f6fa;color:#1d3044;font:15px Arial,Helvetica,sans-serif}.wrap{max-width:900px;margin:25px auto;padding:0 15px}.card{background:white;border:1px solid #dce5ef;border-radius:12px;padding:25px;margin-bottom:15px}.head{border-top:5px solid #183e63}h1{font-size:24px;margin:15px 0 8px}h2{font-size:17px;color:#173b5f}p{line-height:1.6}.muted{color:#687c90}.body{white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere;font-size:14px;color:#25374a;min-height:450px}.document-paper{max-width:794px;margin:0 auto 18px;padding:52px 55px!important;box-shadow:0 8px 28px #1b345112;border-radius:3px!important}.doc-top{border-bottom:2px solid #173e64;padding-bottom:18px;margin-bottom:26px;display:flex;justify-content:space-between;align-items:center;gap:15px}.doc-top strong{font-size:22px;letter-spacing:1px;color:#173e64}.doc-top small{display:block;color:#647d96;font-size:10px;letter-spacing:2px}.doc-footer{margin-top:35px;border-top:1px solid #d8e2ec;padding-top:12px;color:#77899b;font-size:11px;text-align:center}.signature-card{max-width:794px;margin-left:auto;margin-right:auto}.signature-card h2{font-size:20px}@media(max-width:650px){.document-paper{padding:24px 19px!important}.doc-top strong{font-size:17px}}.pad{border:2px dashed #a4b8cd;border-radius:9px;background:#fff;touch-action:none;margin:12px 0}.pad canvas{display:block;width:100%;height:220px;touch-action:none}input[type=text]{box-sizing:border-box;width:100%;padding:12px;border:1px solid #bdccda;border-radius:7px;font:inherit}.btn{border:0;background:#174b7c;color:white;padding:12px 17px;border-radius:7px;cursor:pointer;font-weight:bold}.alt{background:#e7eef5;color:#254663}.error{color:#9c2222}.success{color:#176b41}label{display:block;margin:12px 0 6px;font-weight:bold}@media(max-width:550px){.card{padding:17px}}.document-frame-card{max-width:940px;margin:0 auto 18px;padding:12px!important}.document-frame-title{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px 15px;flex-wrap:wrap}.document-frame-title a{font-size:13px;color:#174b7c}.document-frame{display:block;width:100%;height:1100px;border:1px solid #dce5ef;border-radius:6px;background:#e7ebef}.signature-card{max-width:940px}@media(max-width:650px){.document-frame{height:750px}.document-frame-card{padding:8px!important}}</style></head><body><main class="wrap"><div class="card head"><strong>EKŞİOĞLU LOJİSTİK</strong><div class="muted">INTERNATIONAL MOVERS</div><h1>Dijital sözleşme ve imza</h1><p class="muted"><?=htmlspecialchars($row['quote_no'],ENT_QUOTES,'UTF-8')?> · <?=htmlspecialchars($row['name'],ENT_QUOTES,'UTF-8')?></p></div><section class="card document-frame-card"><div class="document-frame-title"><strong>EKŞİOĞLU LOJİSTİK · Sözleşme Belgesi</strong><a href="customer-contract-document.php?token=<?=rawurlencode($token)?>" target="_blank" rel="noopener noreferrer">Belgeyi ayrı aç / PDF kaydet ↗</a></div><iframe class="document-frame" title="Sözleşme PDF önizlemesi" src="customer-contract-document.php?token=<?=rawurlencode($token)?>" loading="eager" referrerpolicy="no-referrer"></iframe><p class="muted" style="font-size:12px">Belge, yönetici panelindeki sözleşme PDF görünümüyle aynı şablondan hazırlanır. Tamamını aşağı kaydırarak inceleyin.</p></section><section class="card signature-card"><h2>Dokunmatik imza</h2><?php if($error):?><p class="error" role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><?php if($signed):?><p class="success">✓ Sözleşme imzalandı. Teşekkür ederiz.</p><?php else:?><p class="muted">Sözleşmeyi okuduktan sonra parmağınızla, kalemle veya fareyle imzalayın.</p><form method="post" enctype="multipart/form-data" id="sign-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="display_hash" value="<?=h($displayHash)?>"><input type="hidden" name="token" value="<?=htmlspecialchars($token,ENT_QUOTES,'UTF-8')?>"><input type="file" name="signature_png" id="sign-data" accept="image/png" hidden><label for="sign-name">Ad soyad</label><input type="text" name="signer_name" id="sign-name" maxlength="190" required value="<?=htmlspecialchars($row['name'],ENT_QUOTES,'UTF-8')?>"><label>İmzanız</label><div class="pad"><canvas id="sign-canvas" aria-label="İmza çizim alanı"></canvas></div><button class="btn alt" type="button" id="clear">İmzayı temizle</button><p><label style="font-weight:normal"><input type="checkbox" name="consent" value="yes" required> Sözleşmenin tamamını okudum, kabul ediyorum ve imzamın kaydedilmesini onaylıyorum.</label></p><button class="btn" type="submit">İmzala ve onayla</button></form><?php endif;?></section></main><script>(()=>{const c=document.getElementById('sign-canvas');if(!c)return;const x=c.getContext('2d'),f=document.getElementById('sign-form'),hidden=document.getElementById('sign-data');let drawing=false,strokes=0;function reset(){const ratio=Math.min(devicePixelRatio||1,2);c.width=Math.round(c.clientWidth*ratio);c.height=Math.round(c.clientHeight*ratio);x.setTransform(ratio,0,0,ratio,0,0);x.fillStyle='#fff';x.fillRect(0,0,c.clientWidth,c.clientHeight);x.strokeStyle='#153c67';x.lineWidth=2.6;x.lineCap='round';x.lineJoin='round';strokes=0}function pos(e){const r=c.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}c.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;c.setPointerCapture(e.pointerId);const p=pos(e);x.beginPath();x.moveTo(p.x,p.y);x.lineTo(p.x+.1,p.y+.1);x.stroke();strokes++});c.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=pos(e);x.lineTo(p.x,p.y);x.stroke();strokes++});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>c.addEventListener(ev,()=>drawing=false));document.getElementById('clear').addEventListener('click',reset);f.addEventListener('submit',e=>{e.preventDefault();if(strokes<6){alert('Lütfen imzanızı çiziniz.');return}c.toBlob(blob=>{if(!blob||blob.size>110000){alert('İmza çok büyük. Yeniden deneyin.');return}const dt=new DataTransfer();dt.items.add(new File([blob],'signature.png',{type:'image/png'}));hidden.files=dt.files;HTMLFormElement.prototype.submit.call(f)},'image/png')});reset()})();</script></body></html>
